/**
 * The server's build version must be an actual JSON marker generated by Vite.
 * An HTML SPA fallback, an offline response or an invalid payload is NOT an update.
 */
export type PublishedVersion = { buildId: string };

export function parsePublishedVersion(value: unknown): PublishedVersion | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const candidate = (value as Record<string, unknown>).buildId;
  if (typeof candidate !== 'string' || !/^[a-zA-Z0-9._-]{10,128}$/.test(candidate)) {
    return null;
  }
  return { buildId: candidate };
}

export function isNewPublishedVersion(
  current: string,
  published: PublishedVersion | null,
): boolean {
  return published !== null && published.buildId !== current;
}
